/****************************************************************************
 * Name: gc2083_i2c_scan
 *
 * Description:
 *   Scan the I2C2 bus for any responding devices.
 *   Probes every 7-bit address from 0x08 to 0x77 with a zero-length write
 *   and reports which addresses ACK.
 *
 *   Call this AFTER gc2083_i2c_init() so the controller is already clocked
 *   and the pinmux / timing parameters are valid.
 *
 ****************************************************************************/

static void gc2083_i2c_scan(void)
{
  int addr;
  int found = 0;
  int timeout;
  uint32_t status;
  uint32_t abrt;

  GC2083_INFO("Scanning I2C2 bus for devices (7-bit addr 0x08..0x77)...");

  for (addr = 0x08; addr <= 0x77; addr++)
    {
      /* 1. Disable controller */
      putreg32(0, SG2000_I2C2_BASE + I2C_ENABLE);
      timeout = 1000;
      while (timeout-- > 0)
        {
          if ((getreg32(SG2000_I2C2_BASE + I2C_ENABLE_STATUS) & 1) == 0)
            break;
          gc2083_delay_ms(1);
        }

      /* 2. Set probe address */
      putreg32(addr, SG2000_I2C2_BASE + I2C_TAR);

      /* 3. Clear any stale TX abort by reading CLR_TX_ABRT */
      (void)getreg32(SG2000_I2C2_BASE + 0x54);

      /* 4. Re-enable controller */
      putreg32(1, SG2000_I2C2_BASE + I2C_ENABLE);

      /* 5. Wait for TX FIFO ready */
      timeout = 100;
      while (timeout-- > 0)
        {
          if (getreg32(SG2000_I2C2_BASE + I2C_STATUS) & I2C_STATUS_TFNF)
            break;
        }

      /* 6. Send a zero-data write + STOP to probe the address */
      putreg32(I2C_CMD_WRITE | I2C_CMD_STOP,
               SG2000_I2C2_BASE + I2C_DATA_CMD);

      /* 7. Wait for transaction to complete (or abort) */
      gc2083_delay_ms(2);

      /* 8. Check TX_ABRT_SOURCE.  bit[0]=ABRT_7B_ADDR_NOACK */
      abrt = getreg32(SG2000_I2C2_BASE + 0x80);

      /* Also read status */
      status = getreg32(SG2000_I2C2_BASE + I2C_STATUS);

      if (!(abrt & 0x01))
        {
          /* No NACK → device exists at this address! */
          GC2083_INFO("  [FOUND] 7-bit: 0x%02X  8-bit W: 0x%02X  R: 0x%02X",
                      addr, addr << 1, (addr << 1) | 1);
          found++;
        }
    }

  /* Re-configure for GC2083 default address before returning */
  putreg32(0, SG2000_I2C2_BASE + I2C_ENABLE);
  timeout = 1000;
  while (timeout-- > 0)
    {
      if ((getreg32(SG2000_I2C2_BASE + I2C_ENABLE_STATUS) & 1) == 0)
        break;
      gc2083_delay_ms(1);
    }
  putreg32(GC2083_I2C_ADDR, SG2000_I2C2_BASE + I2C_TAR);
  (void)getreg32(SG2000_I2C2_BASE + 0x54);
  putreg32(1, SG2000_I2C2_BASE + I2C_ENABLE);

  if (found == 0)
    {
      GC2083_ERR("No devices found on I2C2 bus! Check wiring/MCLK/power.");
    }
  else
    {
      GC2083_INFO("Scan complete: %d device(s) found on I2C2 bus", found);
    }
}

