/****************************************************************************
 * Name: gc2083_pin_test
 *
 * Description:
 *   Switch SCL / SDA / MCLK pads back to GPIO mode and read their input
 *   levels.  This is a hardware connectivity sanity check: if a pad reads 0
 *   with the internal pull-down disabled it may be shorted or disconnected.
 *
 ****************************************************************************/

static void gc2083_pin_test(void)
{
  uint32_t base = SG2000_GPIO_BASE + GPIO_PORT_C * 0x1000;
  uint32_t reg;
  uint32_t scl_val, sda_val, mclk_val;

  GC2083_INFO("=== Pin Connectivity Test ===");

  /* Step 1: Read SDA (PAD_MIPI_TXM1, XGPIOC14) */
  reg = getreg32(SG2000_FMUX_BASE + FMUX_PAD_MIPI_TXM1);
  reg = (reg & ~0x7) | 0x3;            /* FUNCSEL 3 = XGPIOC[14] */
  putreg32(reg, SG2000_FMUX_BASE + FMUX_PAD_MIPI_TXM1);

  reg = getreg32(base + GPIO_OEN);
  reg |= (1 << 14);                     /* Set as input */
  putreg32(reg, base + GPIO_OEN);

  gc2083_delay_ms(1);
  sda_val = getreg32(base + GPIO_OUTPUT);  /* Read pin state */
  GC2083_INFO("  SDA  (XGPIOC14): %s", (sda_val & (1 << 14)) ? "HIGH" : "LOW");

  /* Step 2: Read SCL (PAD_MIPI_TXP1, XGPIOC15) */
  reg = getreg32(SG2000_FMUX_BASE + FMUX_PAD_MIPI_TXP1);
