  gc2083_delay_ms(1);
  mclk_val = getreg32(base + GPIO_OUTPUT);
  GC2083_INFO("  MCLK (XGPIOC13): %s", (mclk_val & (1 << 13)) ? "HIGH" : "LOW");

  /* Step 4: Enable MCLK pin as OUTPUT and toggle it HIGH→LOW→HIGH.
   * After each write, read back the pin state to verify the GPIO
   * actually drives the pad.  If reads don't match writes the pad may
   * be shorted.
   */

  GC2083_INFO("  Testing MCLK toggle...");

  reg = getreg32(base + GPIO_OEN);
  reg &= ~(1 << 13);                    /* Output */
  putreg32(reg, base + GPIO_OEN);

  /* Drive HIGH */
  reg = getreg32(base + GPIO_OUTPUT);
  reg |= (1 << 13);
  putreg32(reg, base + GPIO_OUTPUT);
  gc2083_delay_ms(1);
  mclk_val = getreg32(base + GPIO_OUTPUT);
  GC2083_INFO("  MCLK write HIGH -> read: %s",
              (mclk_val & (1 << 13)) ? "HIGH" : "LOW");

  /* Drive LOW */
  reg = getreg32(base + GPIO_OUTPUT);
  reg &= ~(1 << 13);
  putreg32(reg, base + GPIO_OUTPUT);
  gc2083_delay_ms(1);
  mclk_val = getreg32(base + GPIO_OUTPUT);
  GC2083_INFO("  MCLK write LOW  -> read: %s",
              (mclk_val & (1 << 13)) ? "HIGH" : "LOW");

  /* Drive HIGH again */
  reg = getreg32(base + GPIO_OUTPUT);
  reg |= (1 << 13);
  putreg32(reg, base + GPIO_OUTPUT);

  GC2083_INFO("=== Pin Test Complete (I2C pins NOT restored!) ===");
}

