/* MCLK probe: keep PAD_MIPI_TXP0 as CAM_MCLK0 (FUNCSEL 4) but read its
 * raw level through the GPIO input path.  If CAM0PLL is really outputting
 * 24 MHz on this pad we will see random HIGH/LOW across samples.
 * If all samples are identically LOW the MCLK output is dead.
 */
{
  int high = 0, low = 0, s;
  uint32_t basec = SG2000_GPIO_BASE + GPIO_PORT_C * 0x1000;

  /* Set XGPIOC13 as GPIO input WITHOUT changing the FMUX.
   * On most SoCs the GPIO input sampler still works even when the
   * pad is muxed to an alternate function.
   */
  s = getreg32(basec + GPIO_OEN);
  s |= (1 << 13);                      /* Input */
  putreg32(s, basec + GPIO_OEN);

  for (s = 0; s < 1000; s++)
    {
      if (getreg32(basec + GPIO_OUTPUT) & (1 << 13))
        high++;
      else
        low++;
    }

  GC2083_INFO("  MCLK probe (GPIO input, CAM_MCLK0 fn): "
              "HIGH=%d LOW=%d (expect ~50/50 if MCLK alive)",
              high, low);

  /* Also probe SCL and SDA the same way: keep I2C2 function, read inputs */
  /* SCL = XGPIOC15 */
  s = getreg32(basec + GPIO_OEN);
  s |= (1 << 15);
  putreg32(s, basec + GPIO_OEN);
  high = low = 0;
  for (s = 0; s < 500; s++)
    {
      if (getreg32(basec + GPIO_OUTPUT) & (1 << 15)) high++;
      else low++;
    }
  GC2083_INFO("  SCL  probe (GPIO input, I2C2_SCL fn): HIGH=%d LOW=%d",
              high, low);

  /* SDA = XGPIOC14 */
  s = getreg32(basec + GPIO_OEN);
  s |= (1 << 14);
  putreg32(s, basec + GPIO_OEN);
  high = low = 0;
  for (s = 0; s < 500; s++)
    {
      if (getreg32(basec + GPIO_OUTPUT) & (1 << 14)) high++;
      else low++;
    }
  GC2083_INFO("  SDA  probe (GPIO input, I2C2_SDA fn): HIGH=%d LOW=%d",
              high, low);
}

