/* Verify RESET pin: it should be HIGH (deasserted) after the reset
 * sequence.  The IOBLK for PAD_MIPI_TXP2 still has PD=1 (0x48), but
 * the GPIO output driver should overcome the weak pull-down.
 * If it reads LOW the sensor may be stuck in reset.
 */
{
  uint32_t basec = SG2000_GPIO_BASE + GPIO_PORT_C * 0x1000;
  uint32_t val;

  /* XGPIOC17 is still muxed as GPIO (done in gc2083_reset). Read it. */
  GC2083_INFO("  RST  (XGPIOC17) OEN=0x%08X OUT=0x%08X",
              getreg32(basec + GPIO_OEN) & (1 << 17),
              getreg32(basec + GPIO_OUTPUT) & (1 << 17));
  GC2083_INFO("  RST  pin state: %s",
              (getreg32(basec + GPIO_OUTPUT) & (1 << 17)) ? "HIGH" : "LOW");

  /* Now set RST as input and read: should be HIGH (PD fighting ext PU) */
  val = getreg32(basec + GPIO_OEN);
  val |= (1 << 17);
  putreg32(val, basec + GPIO_OEN);
  gc2083_delay_ms(1);
  GC2083_INFO("  RST  as input: %s",
              (getreg32(basec + GPIO_OUTPUT) & (1 << 17)) ? "HIGH" : "LOW");

  /* Restore RST as output HIGH */
  val = getreg32(basec + GPIO_OEN);
  val &= ~(1 << 17);
  putreg32(val, basec + GPIO_OEN);
  val = getreg32(basec + GPIO_OUTPUT);
  val |= (1 << 17);
  putreg32(val, basec + GPIO_OUTPUT);
}

