  /* 2d. Set sync source enable (pll_g2_ssc_syn_ctrl, offset 0x040) */
  reg = getreg32(SG2000_PLL_G2_BASE + PLL_G2_SYNC_CTRL);
  reg |= PLL_G2_SYNC_SRC_EN;
  putreg32(reg, SG2000_PLL_G2_BASE + PLL_G2_SYNC_CTRL);

  /* 2e. Set sync set value (VCO frequency) */
  putreg32(CAM0PLL_SYNC_SET_VAL,
           SG2000_PLL_G2_BASE + CAM0PLL_SYNC_SET);

  /* 2f. Trigger sync set update (toggle bit 0) */
  reg = getreg32(SG2000_PLL_G2_BASE + CAM0PLL_SYNC_CTRL);
  reg ^= 0x01;
  putreg32(reg, SG2000_PLL_G2_BASE + CAM0PLL_SYNC_CTRL);

  /* 2g. Set CAM0PLL CSR (pre_div, post_div, sel_mode, div_sel, ictrl) */
  reg = CAM0PLL_PRE_DIV |
        (CAM0PLL_POST_DIV << 8) |
        (CAM0PLL_SEL_MODE << 15) |
        (CAM0PLL_DIV_SEL << 17) |
        (CAM0PLL_ICTRL << 24);
  putreg32(reg, SG2000_PLL_G2_BASE + CAM0PLL_CSR);

  /* 2g2. Disable pdiv auto power-down while PLL is still powered down.
   * cam0pll_clk_csr (0x030028AC) bit[8] = pdiv_auto_pd.
   * The SG2000 hardware rejects writes to this register when the PLL
   * is running.  Writing while PWD=1 (powered down) should succeed.
   */
  GC2083_DEBUG("cam0pll_clk_csr (PLL off) before = 0x%08X",
               getreg32(SG2000_PLL_G2_BASE + 0x0AC));
  reg = getreg32(SG2000_PLL_G2_BASE + 0x0AC);
  reg &= ~(1u << 8);   /* Disable pdiv auto power-down */
  putreg32(reg, SG2000_PLL_G2_BASE + 0x0AC);
  GC2083_DEBUG("cam0pll_clk_csr (PLL off) after  = 0x%08X",
               getreg32(SG2000_PLL_G2_BASE + 0x0AC));

  /* 2h. Power up CAM0PLL (de-assert PWD) */
  reg = getreg32(SG2000_PLL_G2_BASE + CAM0PLL_CTRL);
  reg &= ~CAM0PLL_PWD;
  putreg32(reg, SG2000_PLL_G2_BASE + CAM0PLL_CTRL);
  gc2083_delay_ms(1);

  /* Verify PLL lock */
  reg = getreg32(SG2000_PLL_G2_BASE + PLL_G2_STATUS);
  if (reg & CAM0PLL_LOCK)
    {
      GC2083_DEBUG("CAM0PLL locked (status=0x%08X)", reg);
    }
  else if (reg & CAM0PLL_UPDATING)
    {
      GC2083_WARN("CAM0PLL still updating (status=0x%08X)", reg);
    }
  else
    {
      GC2083_WARN("CAM0PLL not locked (status=0x%08X)", reg);
    }

  /* 2i. Enable CAM0 clock gate */
  reg = getreg32(SG2000_CLK_BASE + 0x008);
  reg |= (1 << 16);
  putreg32(reg, SG2000_CLK_BASE + 0x008);

  /* Dump final MCLK source/divider register for verification */
  reg = getreg32(SG2000_CLK_BASE + CAM0PLL_DIV_REG);
  GC2083_DEBUG("clk_cam0_src_div = 0x%08X", reg);

  GC2083_DEBUG("MCLK output enabled on XGPIOC13 (24MHz)");

  return OK;
}

