static int gc2083_mclk_enable(void)
{
  uint32_t reg;

  GC2083_INFO("Enabling MCLK output (24MHz)...");

  /* Step 1: Configure pinmux for XGPIOC13 as CAM_MCLK0
   * PAD_MIPI_TXP0 -> function 4 = CAM_MCLK0
   */
  reg = getreg32(SG2000_FMUX_BASE + FMUX_PAD_MIPI_TXP0);
  reg = (reg & ~0x7) | 0x4;
  putreg32(reg, SG2000_FMUX_BASE + FMUX_PAD_MIPI_TXP0);

  GC2083_DEBUG("MCLK pinmux configured (PAD_MIPI_TXP0 -> CAM_MCLK0)");

  /* Step 2: FSBL + U-Boot already configured CAM0PLL and pinmux.
   * We must NOT power-cycle the PLL — that would disrupt clocks that
   * other modules (VIP/CIF) may already be using.
   *
   * Just verify the PLL is locked, then set the MCLK divider + source
   * and enable the clock gate.  This is equivalent to what Linux does
   * via clk_set_rate() + clk_prepare_enable(clk_cam0).
   */

  /* 2a. Verify CAM0PLL is still locked (FSBL set it up) */
  reg = getreg32(SG2000_PLL_G2_BASE + PLL_G2_STATUS);
  GC2083_DEBUG("PLL_G2_STATUS = 0x%08X", reg);
  if (!(reg & CAM0PLL_LOCK))
    {
      GC2083_ERR("CAM0PLL not locked! FSBL may not have initialized it.");
      return -ENODEV;
    }
  GC2083_DEBUG("CAM0PLL locked (FSBL configured)");

  /* 2b. Set MCLK divider and source.
   * REG_CLK_CAM0_SRC_DIV (0x030028C0):
   *   bits[21:16] = divider (25)
   *   bits[9:8]   = 2 (cam0pll_d2)
   */
  reg = getreg32(SG2000_CLK_BASE + CAM0PLL_DIV_REG);
  reg &= ~((0x3F << 16) | (0x3 << 8));
  reg |= (CAM0PLL_MCLK_DIV << 16) | (CAM0PLL_MCLK_SRC << 8);
  putreg32(reg, SG2000_CLK_BASE + CAM0PLL_DIV_REG);
  GC2083_DEBUG("clk_cam0_src_div = 0x%08X",
               getreg32(SG2000_CLK_BASE + CAM0PLL_DIV_REG));

  /* 2c. Enable clk_cam0 gate (REG_CLK_EN_2 bit 16).
   * This tells the clock controller that MCLK is in use, which should
   * cause the hardware to release any auto power-down on the pdiv path.
   */
  reg = getreg32(SG2000_CLK_BASE + 0x008);
  reg |= (1 << 16);
  putreg32(reg, SG2000_CLK_BASE + 0x008);
  GC2083_DEBUG("REG_CLK_EN_2 bit16 set: 0x%08X",
               getreg32(SG2000_CLK_BASE + 0x008));

  GC2083_DEBUG("MCLK output enabled on XGPIOC13 (24MHz)");

  return OK;
}

