/* CRITICAL TEST: Verify GPIO input sampler works when pads are in
 * alternate-function (I2C) mode.  If the sampler is disconnected in
 * non-GPIO modes, our MCLK/SCL/SDA probes above are FALSE NEGATIVES.
 *
 * Method: drive SDA HIGH via GPIO, switch to I2C2 function, immediately
 * read GPIO input.  The pad capacitance should hold the level briefly.
 */
{
  uint32_t basec = SG2000_GPIO_BASE + GPIO_PORT_C * 0x1000;
  uint32_t val;
  int s;

  /* SDA = XGPIOC14, MUX to GPIO, output, drive HIGH */
  GC2083_INFO("  GPIO→I2C transition test on SDA:");
  val = getreg32(SG2000_FMUX_BASE + FMUX_PAD_MIPI_TXM1);
  val = (val & ~0x7) | 0x3;           /* GPIO fn */
  putreg32(val, SG2000_FMUX_BASE + FMUX_PAD_MIPI_TXM1);

  val = getreg32(basec + GPIO_OEN);
  val &= ~(1 << 14);                   /* Output */
  putreg32(val, basec + GPIO_OEN);

  val = getreg32(basec + GPIO_OUTPUT);
  val |= (1 << 14);                    /* Drive HIGH */
  putreg32(val, basec + GPIO_OUTPUT);
  gc2083_delay_ms(1);

  /* Read back in GPIO output mode (should be HIGH) */
  GC2083_INFO("    GPIO out HIGH → read: %s",
      (getreg32(basec + GPIO_OUTPUT) & (1 << 14)) ? "HIGH" : "LOW");

  /* Now switch to I2C2 function (FUNCSEL 4) WITHOUT changing GPIO */
  val = getreg32(SG2000_FMUX_BASE + FMUX_PAD_MIPI_TXM1);
  val = (val & ~0x7) | 0x4;           /* I2C2 fn */
  putreg32(val, SG2000_FMUX_BASE + FMUX_PAD_MIPI_TXM1);

  /* Immediately sample GPIO input (set OEN=input first) */
  val = getreg32(basec + GPIO_OEN);
  val |= (1 << 14);                    /* Input */
  putreg32(val, basec + GPIO_OEN);

  s = 0;
  GC2083_INFO("    I2C2 fn, GPIO input readback (10 samples):");
  for (int k = 0; k < 10; k++)
    {
      int v = (getreg32(basec + GPIO_OUTPUT) & (1 << 14)) ? 1 : 0;
      GC2083_INFO("      sample %d: %s", k, v ? "HIGH" : "LOW");
      s += v;
    }
  GC2083_INFO("    HIGH=%d/10 (expect ~10 if sampler works, ~0 if dead)", s);

  /* Restore I2C function and IOBLK */
  val = getreg32(SG2000_FMUX_BASE + FMUX_PAD_MIPI_TXM1);
  val = (val & ~0x7) | 0x4;
  putreg32(val, SG2000_FMUX_BASE + FMUX_PAD_MIPI_TXM1);
  val = getreg32(SG2000_IOBLK_G12_BASE + IOBLK_PAD_MIPI_TXM1);
  val |= IOBLK_PU;
  val &= ~IOBLK_PD;
  putreg32(val, SG2000_IOBLK_G12_BASE + IOBLK_PAD_MIPI_TXM1);
}

