/* Fix MCLK pad: disable pull-down.  PD=1 on an output clock pad
 * may attenuate the signal. */
{
  uint32_t io = getreg32(SG2000_IOBLK_G12_BASE + IOBLK_PAD_MIPI_TXP0);
  io &= ~IOBLK_PD;   /* Disable pull-down */
  io |= IOBLK_PU;    /* Enable pull-up (weak, won't affect clock out) */
  putreg32(io, SG2000_IOBLK_G12_BASE + IOBLK_PAD_MIPI_TXP0);
}

